.sl-stats-countdown {
    padding-block: clamp(3rem, 6vw, 4.5rem);
    background-color: #0f172a;
    background: linear-gradient(135deg, color-mix(in srgb, var(--smartlearn-primary) 55%, #0f172a) 0%, #0f172a 100%);
    position: relative;
    overflow: hidden;
    font-family: var(--smartlearn-body-font, system-ui, sans-serif);
}

.sl-stats-countdown::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image: url('data:image/svg+xml;utf8,<svg width="20" height="20" viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg"><circle cx="2" cy="2" r="2" fill="rgba(255,255,255,0.06)"/></svg>');
    background-size: 20px 20px;
    z-index: 0;
    pointer-events: none;
}

.sl-stats-countdown .container {
    position: relative;
    z-index: 1;
}

.sl-stats-countdown .sl-countdown-wrapper {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 2.5rem;
}

@media (min-width: 992px) {
    .sl-stats-countdown .sl-countdown-wrapper {
        flex-direction: row;
        justify-content: space-between;
        text-align: start;
    }
}

.sl-stats-countdown .sl-countdown-content {
    flex: 1;
    max-width: 500px;
}

.sl-stats-countdown .sl-countdown-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.5rem, 3vw, 2rem);
    font-weight: 800;
    color: #ffffff;
    margin-bottom: 0.75rem;
}

.sl-stats-countdown .sl-countdown-desc {
    font-size: 1.125rem;
    color: rgba(255, 255, 255, 0.9);
    margin: 0;
}

.sl-stats-countdown .sl-countdown-timer-group {
    display: flex;
    align-items: center;
    justify-content: center;
}

.sl-stats-countdown .sl-countdown-timer {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background-color: rgba(0, 0, 0, 0.35);
    padding: 1.5rem 2rem;
    border-radius: var(--smartlearn-radius, 1rem);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.16);
}

.sl-stats-countdown .sl-hidden-state {
    display: none !important;
}

.sl-stats-countdown .sl-countdown-expired {
    background-color: rgba(0, 0, 0, 0.45);
    padding: 1.5rem 2rem;
    border-radius: var(--smartlearn-radius, 1rem);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.25);
}

.sl-stats-countdown .sl-expired-msg {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: #ffffff;
    font-size: 1.25rem;
    font-weight: 600;
}

@media (max-width: 575px) {
    .sl-stats-countdown .sl-countdown-timer {
        padding: 1rem;
        gap: 0.25rem;
    }
    .sl-stats-countdown .sl-time-block {
        min-width: 52px;
    }
}

.sl-stats-countdown .sl-time-block {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 60px;
}

.sl-stats-countdown .sl-time-val {
    font-size: clamp(1.75rem, 4vw, 2.5rem);
    font-weight: 800;
    color: #ffffff;
    line-height: 1;
    font-variant-numeric: tabular-nums;
}

.sl-stats-countdown .sl-time-lbl {
    font-size: 0.75rem;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.88);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-top: 0.5rem;
}

.sl-stats-countdown .sl-time-sep {
    font-size: 2rem;
    font-weight: 700;
    color: rgba(255, 255, 255, 0.55);
    margin-top: -1.5rem;
}

.sl-stats-countdown .sl-countdown-action {
    flex-shrink: 0;
}

.sl-stats-countdown .sl-countdown-cta {
    display: inline-block;
    padding: 1rem 2.5rem;
    border-radius: var(--smartlearn-radius, 0.5rem);
    font-weight: 700;
    font-size: 1.125rem;
    text-decoration: none;
    transition: transform 0.2s ease, background-color 0.2s ease;
    white-space: nowrap;
    background-color: #ffffff;
    color: #0f172a;
    border: 2px solid #ffffff;
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.15);
}

.sl-stats-countdown .sl-countdown-cta:hover {
    background-color: #f1f5f9;
    color: #0f172a;
    transform: translateY(-2px);
}

.sl-stats-countdown .sl-countdown-cta:focus-visible {
    outline: 2px solid #ffffff;
    outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
    .sl-stats-countdown .sl-countdown-cta {
        transition: none;
    }
    .sl-stats-countdown .sl-countdown-cta:hover {
        transform: none;
    }
}

