(function() {
    function resolveTargetDate(wrapper, root) {
        var deadlineEl = root.querySelector('.sl-static-deadline');
        var deadlineText = deadlineEl ? deadlineEl.textContent.trim() : '';
        var parsedText = deadlineText ? Date.parse(deadlineText) : NaN;
        var attrStr = wrapper.getAttribute('data-target-date');

        if (!isNaN(parsedText)) {
            return parsedText;
        }
        if (attrStr && attrStr !== 'auto') {
            var attrTime = new Date(attrStr).getTime();
            if (!isNaN(attrTime)) return attrTime;
        }
        var d = new Date();
        d.setDate(d.getDate() + 14);
        return d.getTime();
    }

    function initCountdown(root) {
        if (!root || root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        var isEditing = Boolean(root.querySelector('[data-sl-edit-id]'));
        var wrapper = root.querySelector('.sl-countdown-wrapper');
        var timerActive = root.querySelector('.sl-countdown-timer');
        var timerExpired = root.querySelector('.sl-countdown-expired');
        if (!wrapper || !timerActive || !timerExpired) return;

        var dEl = root.querySelector('[data-sl-unit="days"]');
        var hEl = root.querySelector('[data-sl-unit="hours"]');
        var mEl = root.querySelector('[data-sl-unit="mins"]');
        var sEl = root.querySelector('[data-sl-unit="secs"]');
        if (!dEl || !hEl || !mEl || !sEl) return;

        var targetDate = resolveTargetDate(wrapper, root);
        var timerId = null;

        function update() {
            var now = Date.now();
            var distance = targetDate - now;

            if (distance <= 0) {
                dEl.textContent = '00';
                hEl.textContent = '00';
                mEl.textContent = '00';
                sEl.textContent = '00';

                if (!isEditing) {
                    timerActive.classList.add('sl-hidden-state');
                    timerExpired.classList.remove('sl-hidden-state');
                }
                if (timerId !== null) {
                    clearInterval(timerId);
                    timerId = null;
                }
                return false;
            }

            var days = Math.floor(distance / (1000 * 60 * 60 * 24));
            var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            var seconds = Math.floor((distance % (1000 * 60)) / 1000);

            dEl.textContent = days.toString().padStart(2, '0');
            hEl.textContent = hours.toString().padStart(2, '0');
            mEl.textContent = minutes.toString().padStart(2, '0');
            sEl.textContent = seconds.toString().padStart(2, '0');
            return true;
        }

        var shouldContinue = update();
        if (shouldContinue && !isEditing) {
            timerId = setInterval(update, 1000);
        }
    }

    function initAll() {
        document.querySelectorAll('.sl-stats-countdown').forEach(initCountdown);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
